/**
 * Brand, contact details, opening hours and the announcement bar.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "site-settings".
 */
export interface SiteSetting {
  id: number;
  siteName: string;
  /**
   * Used to format every menu price.
   */
  currency: 'IDR' | 'USD';
  tagline?: string | null;
  /**
   * Optional. The wordmark is used when empty.
   */
  logo?: (number | null) | Media;
  email?: string | null;
  phone?: string | null;
  /**
   * Number in international format, digits only — e.g. 6281234567890.
   */
  whatsapp?: string | null;
  address?: string | null;
  mapUrl?: string | null;
  socials?:
    | {
        platform: 'instagram' | 'tiktok' | 'facebook' | 'x' | 'youtube' | 'gofood' | 'grabfood';
        url: string;
        id?: string | null;
      }[]
    | null;
  hours?:
    | {
        days: string;
        time: string;
        id?: string | null;
      }[]
    | null;
  announcementEnabled?: boolean | null;
  announcement?: string | null;
  announcementLink?: {
    type?: ('reference' | 'custom') | null;
    newTab?: boolean | null;
    reference?: (number | null) | Page;
    url?: string | null;
    label?: string | null;
  };
  updatedAt?: string | null;
  createdAt?: string | null;
}
/**
 * Top info bar, main navigation, the scrolling ticker and the mobile menu.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "header".
 */
export interface Header {
  id: number;
  /**
   * On desktop the first half sits left of the logo and the rest on the right.
   */
  navItems?:
    | {
        link: {
          type?: ('reference' | 'custom') | null;
          newTab?: boolean | null;
          reference?: (number | null) | Page;
          url?: string | null;
          label: string;
        };
        /**
         * Shown in the mobile menu.
         */
        icon?: ('home' | 'bag' | 'cloche' | 'gift' | 'info' | 'mail' | 'menu' | 'coffee' | 'pin') | null;
        /**
         * Small pink tag in the mobile menu.
         */
        badge?: string | null;
        id?: string | null;
      }[]
    | null;
  cta?: {
    type?: ('reference' | 'custom') | null;
    newTab?: boolean | null;
    reference?: (number | null) | Page;
    url?: string | null;
    label?: string | null;
    appearance?: ('primary' | 'outline' | 'link') | null;
  };
  /**
   * The header button is also listed second in the mobile menu, with this tag.
   */
  ctaBadge?: string | null;
  /**
   * The thin blue strip above the navigation (desktop). Every other item is yellow.
   */
  infoBar?:
    | {
        text: string;
        id?: string | null;
      }[]
    | null;
  /**
   * Scrolling facts under the navigation, separated by ★.
   */
  ticker?:
    | {
        text: string;
        id?: string | null;
      }[]
    | null;
  /**
   * Address, hours and phone come from Site settings.
   */
  contactHeading?: string | null;
  promo?: {
    eyebrow?: string | null;
    heading?: string | null;
    link?: {
      type?: ('reference' | 'custom') | null;
      newTab?: boolean | null;
      reference?: (number | null) | Page;
      url?: string | null;
      label?: string | null;
    };
  };
  updatedAt?: string | null;
  createdAt?: string | null;
}
